<script module lang="ts">
/**
 * A stacked area chart for part-to-whole change over time (`design/components/area-chart.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/area-chart.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  DEFAULT_RANGE_MESSAGES,
  Icon,
  UNMEASURED,
  agentMember,
  areaChartModel,
  areaChartReadout,
  areaChartSelection,
  brushChartRange,
  brushDrawing,
  brushSpan,
  brushValues,
  chartHiddenSeries,
  chartMarks,
  chartPosition,
  chartRange,
  chartSeries,
  chooseChartMark,
  createBrush,
  createReading,
  createSyncMember,
  createWarningLog,
  devWarning,
  joinSlot,
  measureBox,
  nearestIndex,
  readChartPosition,
  readingRest,
  readingView,
  syncIndexOf,
  syncValueAt,
  toggleChartSeries,
  toggleSeries,
  watchEffect,
  type ChartAnnotation,
  type ChartBaseline,
  type ChartMessages,
  type ChartSeries,
  type ChartTooltipConfig,
  type ChartXAxis,
  type ChartYAxis,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/charts/area-chart.module.css'
import a11y from '@polymorph/recipes/conventions/a11y.module.css'
import chartAxis from '@polymorph/recipes/charts/frame/chart-axis.module.css'
import chartBrush from '@polymorph/recipes/charts/frame/chart-brush.module.css'
import chartFrame from '@polymorph/recipes/charts/frame/chart-frame.module.css'
import chartLegend from '@polymorph/recipes/charts/frame/chart-legend.module.css'
import chartNotes from '@polymorph/recipes/charts/frame/chart-annotations.module.css'
import chartTooltip from '@polymorph/recipes/charts/frame/chart-tooltip.module.css'
import chartTwin from '@polymorph/recipes/charts/frame/chart-twin.module.css'
import Button from '../controls/Button.svelte'
import Table from '../structure/Table.svelte'
import TableBody from '../structure/TableBody.svelte'
import TableCell from '../structure/TableCell.svelte'
import TableHead from '../structure/TableHead.svelte'
import TableHeader from '../structure/TableHeader.svelte'
import TableRow from '../structure/TableRow.svelte'

export interface AreaChartProps {
  /**
   * Annotations from the closed union above: line, band and point, literals only. The frame's
   * shared annotation layer draws them in `--pm-chart-axis`, with bands washed in
   * `--pm-chart-other` at 0.08. An annotation never re-centres colour. Colliding labels are
   * dropped, but the annotation itself always draws because the app asked for it explicitly.
   */
  annotations?: readonly ChartAnnotation[]
  baseline?: ChartBaseline
  /**
   * The data rows. `[]` renders the built-in empty state.
   */
  data: readonly Readonly<Record<string, string | number | null>>[]
  /**
   * Key of the series to emphasise. It keeps its slot colour and the rest use
   * `--pm-chart-other`. A status-toned series keeps its status colour, because reserved meaning
   * is never greyed out.
   */
  emphasis?: string
  /**
   * The chart's accessible name. It is required, as for Progress, because an unnamed chart tells
   * a reader nothing.
   */
  label: string
  /**
   * Loading state. On first render the frame shows a quiet `Skeleton`; on refetch it shows the
   * previous frame at reduced opacity, with no layout jump or flash. Failure is not a chart
   * state: the app reports errors, and a chart shows only data, never network status.
   */
  loading?: boolean
  /**
   * The locale `Intl` formats with. When omitted, the runtime's own resolved locale applies.
   */
  locale?: string
  /**
   * The tier's message catalog. When omitted, the generic English defaults apply. A localized
   * host passes its own, the same object to every chart on the screen.
   */
  messages?: ChartMessages
  /**
   * Enables the range brush, for a `time` x only: this member takes no `linear` x and a band has
   * no continuum. The brush reports a committed range and never filters the chart itself. It
   * passes ISO strings and fires on commit only.
   */
  onBrushEnd?: (range: [number, number] | [string, string]) => void
  /**
   * Called with the row at the reading position, on Enter, Space or click.
   */
  onSelect?: (selection: {
    index: number
    datum: Readonly<Record<string, string | number | null>>
  }) => void
  /**
   * The series to draw, 1–8. A ninth gets a dev-warning about folding into "Other", never a
   * generated hue, because the wheel has eight seats.
   */
  series: readonly ChartSeries[]
  /**
   * Frame height, from `--pm-chart-height-*`. The frame never nests a scroll region.
   */
  size?: 'sm' | 'md' | 'lg'
  /**
   * Syncs the reading position across sibling charts. The broadcast is the x-domain value, never
   * the row index, and Escape or blur clears the whole group. The registry works as described in
   * `line-chart.md`.
   */
  syncId?: string
  /**
   * Tooltip configuration, on with `'dot'` by default. `false`, for print and report surfaces,
   * removes only the visual layer.
   */
  tooltip?: false | ChartTooltipConfig
  /**
   * `percent` normalizes each x to 100%, to show shares instead of volumes.
   */
  variant?: 'stacked' | 'percent'
  x: ChartXAxis
  /**
   * Y axis configuration. The axis renders by default.
   */
  y?: ChartYAxis
}
</script>

<script lang="ts">
let {
  annotations,
  baseline,
  data,
  emphasis,
  label: labelOwn,
  loading = false,
  locale,
  messages = (() => DEFAULT_RANGE_MESSAGES)(),
  onBrushEnd,
  onSelect,
  series,
  size = 'md',
  syncId,
  tooltip = (() => ({}))(),
  variant = 'stacked',
  x,
  y,
}: AreaChartProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn, size: size }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const listening = {
  get brushEnd() {
    return onBrushEnd !== undefined
  },
  get select() {
    return onSelect !== undefined
  },
}
let box = $state(UNMEASURED)
let reading = $state(createReading({ count: 0, seriesStart: null }))
let position = $state(readingRest(null))
let hidden = $state(new Set<string>())
let twinOpen = $state(false)
let warningLog = $state(createWarningLog())
let brush = $state(
  createBrush({ enabled: false, count: 0, positions: [], onCommit: () => undefined }),
)
let brushed = $state(brush.state())
let sync = $state(createSyncMember((value) => receive(value)))
let receiving = $state(false)
let frame = $state<HTMLElement | null>(null)
let plot = $state<HTMLElement | null>(null)
const input = $derived({
  data,
  series,
  x,
  y,
  variant,
  emphasis,
  baseline,
  annotations,
  label,
  locale,
  messages,
  tooltip,
  loading,
  selectable: listening.select,
  brushable: listening.brushEnd,
  syncId,
  hidden,
  box,
})
const model = $derived(areaChartModel(input))
const view = $derived(readingView(position, data.length))
const readout = $derived(areaChartReadout(input, model, view))
const walk = $derived({ count: data.length })
const rangeSpan = $derived(brushed === null ? null : brushSpan(model, brush.state(data.length)))
const rangeDrawing = $derived(
  rangeSpan === null ? null : brushDrawing(rangeSpan.from, rangeSpan.to, rangeSpan.height),
)
const commit = $derived((anchor: number, edge: number) => {
  const values = brushValues(input, model, anchor, edge)
  if (values !== null) onBrushEnd?.(values)
})
const updateBrush = $derived(() =>
  brush.update({
    enabled: model.brushOn,
    count: data.length,
    positions: model.positions,
    onCommit: commit,
  }),
)
const send = $derived((index: number | null) => {
  if (receiving) return
  const value = syncValueAt(model, index)
  if (value !== undefined) sync.broadcast(value)
})
const receive = $derived((value: number | null) => {
  receiving = true
  const at = syncIndexOf(model, value)
  if (at !== undefined) reading.moveTo(at)
  receiving = false
})
const activate = $derived(() => {
  const selected = areaChartSelection(input, model, reading.now())
  if (selected !== null) onSelect?.(selected)
})
const onKey = $derived((event: KeyboardEvent) => {
  updateBrush()
  if (brush.key(event.key, event.shiftKey, reading)) {
    event.preventDefault()
    return
  }
  if (listening.select && (event.key === 'Enter' || event.key === ' ')) {
    event.preventDefault()
    activate()
    return
  }
  reading.update(walk)
  if (reading.key(event.key)) event.preventDefault()
})
const onPress = $derived((event: PointerEvent) => {
  if (!model.brushOn) return
  updateBrush()
  const rect = (event.currentTarget as Element).getBoundingClientRect()
  brush.pointerDown(event.clientX - rect.left)
  try {
    ;(event.currentTarget as Element).setPointerCapture(event.pointerId)
  } catch {
    /* a synthetic pointer has nothing to capture; the brush still works */
  }
})
const onPointer = $derived((event: PointerEvent) => {
  if (model.plot === null) return
  updateBrush()
  const rect = (event.currentTarget as Element).getBoundingClientRect()
  const px = event.clientX - rect.left
  reading.moveTo(nearestIndex(model.positions, px))
  brush.pointerMove(px)
})
const onClick = $derived(() => {
  if (brush.consumeClick()) return
  activate()
})
const onLeave = $derived(() => {
  brush.blur()
  reading.clear()
})
const marks = $derived({
  walk,
  input,
  model,
  readout: areaChartReadout,
  selection: areaChartSelection,
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const run = () => {
    box = plot === null ? box : measureBox(plot, box)
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [plot]) if (element) resize?.observe(element)
  release1 = () => {
    resize?.disconnect()
  }
  run()
}
watchEffect(effect1)
onDestroy(() => release1?.())
const effect2 = () => {
  reading.subscribe((now) => {
    position = now
  })
}
watchEffect(effect2)
const effect3 = () => {
  warningLog.log(model.warnings, (message) => devWarning(true, message))
}
watchEffect(effect3, { watch: () => model.warnings.join('\n') })
const effect4 = () => {
  brush.subscribe(() => {
    brushed = brush.state()
  })
}
watchEffect(effect4)
let release5: (() => void) | undefined
const effect5 = () => {
  release5?.()
  sync.join(model.syncGroup, plot)
  release5 = () => {
    sync.leave()
  }
}
watchEffect(effect5, { watch: () => model.syncGroup })
onDestroy(() => release5?.())
const effect6 = () => {
  reading.subscribe((now, was) => {
    if (now.index !== was.index) send(now.index)
  })
}
watchEffect(effect6)
let release7: (() => void) | undefined
const effect7 = () => {
  release7?.()
  const ran =
    !listening.select && !model.legend && !model.brushOn
      ? () => {}
      : agentMember({
          member: 'AreaChart',
          element: () => frame,
          state: () => ({
            items: listening.select ? chartMarks(marks, reading) : [],
            position: chartPosition(marks, reading),
            count: walk.count,
            series: chartSeries(frame, chartLegend.key, model.painted),
            hidden: chartHiddenSeries(frame, chartLegend.key, model.painted),
            'range-start': chartRange(marks, brush).start,
            'range-end': chartRange(marks, brush).end,
          }),
          actions: {
            read: { argument: 'number', run: (value) => readChartPosition(marks, value, reading) },
            choose: {
              argument: 'id',
              among: 'items',
              run: (value) => chooseChartMark(marks, value, reading, activate),
            },
            toggle: {
              argument: 'id',
              among: 'series',
              run: (value) => toggleChartSeries(frame, chartLegend.key, model.painted, value),
            },
            brush: {
              argument: 'number',
              run: (value) =>
                (() => {
                  updateBrush()
                  brushChartRange(marks, value, brush, reading)
                })(),
            },
          },
        })
  release7 = () => {
    ran()
  }
}
watchEffect(effect7)
onDestroy(() => release7?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<figure
    bind:this={frame}
    class={chartFrame.frame}
    data-size={size}
    data-state={model.state}
    data-position={view.active ? view.index : undefined}
    aria-label={label}
    data-member="area-chart"
    ><div class={chartFrame.region}
      ><div class={chartFrame.yAxis}
        >{#if (model.axes?.y) !== undefined
          }<div class={chartAxis.axis} data-orientation="y" aria-hidden="true"
            >{#each (model.axes?.y) ?? [] as tick (tick.key)
              }<span class={chartAxis.tick} style:top={`${tick.at}px`} data-align={tick.align}
                >{tick.label
              }</span
            >{/each
          }</div
        >{/if
      }</div
      ><div bind:this={plot} class={chartFrame.plot}
        >{#if model.state === 'empty'
          }<div class={chartFrame.empty}><span>{messages.empty}</span></div
        >{:else
          }<div
            class={styles.surface}
            tabindex="0"
            role="img"
            aria-label={label}
            onkeydown={(event) => { onKey(event) }}
            onclick={() => { onClick() }}
            onpointerdown={(event) => { onPress(event) }}
            onpointermove={(event) => { onPointer(event) }}
            onpointerup={() => { brush.pointerUp() }}
            onpointerleave={() => { reading.clear() }}
            onblur={() => { onLeave() }}
            >{#if model.plot !== null
              }<svg
                class={styles.marks}
                data-variant={variant}
                width={model.plot?.width}
                height={model.plot?.height}
                aria-hidden="true"
                focusable="false"
                ><g class={styles.grid}
                  >{#each model.plot?.grid ?? [] as line (line.key)}<path d={line.d}></path>{/each
                }</g
                >{#if rangeDrawing !== null
                  }<g class={chartBrush.brush}
                    ><rect
                      class={chartBrush.range}
                      x={rangeDrawing?.x}
                      y={0}
                      width={rangeDrawing?.width}
                      height={rangeDrawing?.height}
                    ></rect
                    ><path class={chartBrush.edge} d={rangeDrawing?.near}></path
                    ><path class={chartBrush.edge} d={rangeDrawing?.far}></path
                  ></g
                >{/if
                }{#if (model.plot?.wash ?? []).length > 0
                  }<g class={chartNotes.washes}
                    >{#each (model.plot?.wash ?? []) as span (span.key)
                      }<rect
                        class={chartNotes.span}
                        x={span.x}
                        y={span.y}
                        width={span.width}
                        height={span.height}
                      ></rect
                    >{/each
                  }</g
                >{/if
                }{#if (model.plot?.ink ?? null) !== null
                  }<g class={chartNotes.ink}
                    >{#each (model.plot?.ink ?? null)?.spans ?? [] as span (span.key)
                      }<g
                        ><path class={chartNotes.edge} d={span.from}></path
                        ><path class={chartNotes.edge} d={span.to}></path
                      ></g
                    >{/each
                    }{#each (model.plot?.ink ?? null)?.rules ?? [] as rule (rule.key)
                      }<path class={chartNotes.rule} d={rule.d}></path
                    >{/each
                    }{#each (model.plot?.ink ?? null)?.marks ?? [] as mark (mark.key)
                      }<circle class={chartNotes.mark} cx={mark.cx} cy={mark.cy} r={mark.r}></circle
                    >{/each
                    }{#each (model.plot?.ink ?? null)?.labels ?? [] as note (note.key)
                      }<text
                        class={chartNotes.label}
                        x={note.x}
                        y={note.y}
                        text-anchor={note.anchor}
                        >{note.text
                      }</text
                    >{/each
                  }</g
                >{/if
                }<g class={styles.bands}
                  >{#each model.plot?.bands ?? [] as band (band.key)
                    }<g style:--pm-chart-mark={band.paint}
                      ><path class={styles.band} d={band.fill}></path
                      ><path class={styles.edge} d={band.edge}></path
                    ></g
                  >{/each
                }</g
                >{#if readout.crosshair !== null
                  }<path class={styles.crosshair} data-active="" d={readout.crosshair}></path
                >{/if
              }</svg
            >{/if
          }</div
        >{/if
        }{#if readout.tooltip !== null
          }<div
            class={chartTooltip.tooltip}
            style:--pm-chart-tip-x={`${readout.tooltip?.x}px`}
            style:--pm-chart-tip-y={`${readout.tooltip?.y}px`}
            data-indicator={readout.tooltip?.indicator}
            data-side={readout.tooltip?.side}
            aria-hidden="true"
            >{#if readout.tooltip?.header !== undefined
              }<p class={chartTooltip.header}>{readout.tooltip?.header}</p
            >{/if
            }<ul class={chartTooltip.rows}
              >{#each readout.tooltip?.rows ?? [] as row (row.key)
                }<li class={chartTooltip.row}
                  ><span class={chartTooltip.key} style:--pm-chart-key={row.paint}></span
                  ><span class={chartTooltip.value}>{row.value}</span
                  ><span class={chartTooltip.label}>{row.label}</span
                ></li
              >{/each
            }</ul
          ></div
        >{/if
      }</div
      ><div class={chartFrame.xAxis}
        >{#if (model.axes?.x) !== undefined
          }<div class={chartAxis.axis} data-orientation="x" aria-hidden="true"
            >{#each (model.axes?.x) ?? [] as tick (tick.key)
              }<span class={chartAxis.tick} style:left={`${tick.at}px`} data-align={tick.align}
                >{tick.label
              }</span
            >{/each
          }</div
        >{/if
      }</div
    ></div
    >{#if model.legend
      }{#if model.painted.length > 0
        }<ul class={styles.legend} data-key-shape="rect"
          >{#each model.painted as entry (entry.key)
            }<li class={chartLegend.item}
              ><button
                class={chartLegend.key}
                type="button"
                aria-pressed={hidden.has(entry.key) ? 'false' : 'true'}
                onclick={() => { hidden = toggleSeries(hidden, entry.key) }}
                ><span
                  class={chartLegend.swatch}
                  style:--pm-chart-key={entry.paint}
                  aria-hidden="true"
                ></span
                >{#if entry.icon !== undefined
                  }<span class={chartLegend.glyph}><Icon name={entry.icon} size="sm" /></span
                >{/if
                }<span class={chartLegend.label}>{entry.label}</span
              ></button
            ></li
          >{/each
        }</ul
      >{/if
    }{/if
    }<span class={a11y.visuallyHidden}>{model.summary}</span
    ><div class={chartTwin.twin} data-state={twinOpen ? 'open' : 'closed'}
      ><div class={chartTwin.toggle}
        ><Button
          variant="ghost"
          tone="neutral"
          size="sm"
          icon="table"
          iconOnly={true}
          label={twinOpen ? messages.hideTable(label) : messages.showTable(label)}
          onClick={() => { twinOpen = !twinOpen }}
      /></div
      >{#if twinOpen
        }<div class={chartTwin.table}
          ><Table label={messages.tableLabel(label)} caption={messages.tableLabel(label)}
            ><TableHead
              ><TableRow
                >{#each model.twin.columns as column (column.key)
                  }<TableHeader numeric={column.numeric}>{column.label}</TableHeader
                >{/each
              }</TableRow
            ></TableHead
            ><TableBody
              >{#each model.twin.rows as row, line (line)
                }<TableRow
                  >{#each row as cell, cellIndex (model.twin.columns[cellIndex]?.key ?? cellIndex)
                    }<TableCell numeric={model.twin.columns[cellIndex]?.numeric}
                      >{cell === '' ? '—' : cell
                    }</TableCell
                  >{/each
                }</TableRow
              >{/each
            }</TableBody
          ></Table
        ></div
      >{/if
    }</div
    ><span class={a11y.visuallyHidden}
      ><div aria-live="polite" aria-atomic="true">{readout.announcement}</div
    ></span
  ></figure
>{/if
}{@render joined.end?.()}
